//! 🔁️ The actual public snapshot hop retains native, metadata and physical ownership together.
use semio_framework_artifact_reference::{ArtifactDialect,Dialect,StandardId,SubsetId};
use semio_framework_os_kernel::{self as store,io_schema::*,io::{register_native_snapshot_codec,io_mechanism::{io_route,io_run_with_snapshot_control}},sqlite_snapshot::*};
use semio_framework_value::{NativeDecodeControl,NativeEncodeControl,ValueError,ValueRefusalKind,native_decoding::NativeDecodeProgress,native_encoding::NativeEncodeProgress};
use std::{io::Write,process::{Command,Stdio}};
const DOMAIN:&str="CREATE TABLE transfer_literal (id INTEGER PRIMARY KEY, literal TEXT NOT NULL);";
fn neutral()->serde_json::Value{serde_json::from_str(include_str!("../../../../../../🔨️modules/🚪️io/🪶️sqlite-snapshot/🧫️fixtures/🔁️transfer/🔣️.json")).unwrap()}
fn dialect()->Dialect{Dialect{artifact_kind:"fixture.sqlite-transfer",standard:StandardId("1"),subset:SubsetId("*")}}
fn reserve<T>(count:usize,control:&mut SqliteSnapshotControl<'_>)->Result<Vec<T>,ValueError>{control.admit_allocation_bytes(count.checked_mul(std::mem::size_of::<T>()).ok_or_else(||ValueError::new(ValueRefusalKind::OwnershipLimit,"transfer fixture backing overflow"))?)?;let mut v=Vec::new();v.try_reserve_exact(count).map_err(|_|ValueError::new(ValueRefusalKind::AllocationFailed,"transfer fixture allocation failed"))?;Ok(v)}
fn copy_decode(text:&str,phase:SqliteSnapshotPhase,control:&mut SqliteSnapshotControl<'_>)->Result<String,ValueError>{control.allocation_stage(phase,|remaining,progress|{let mut callback=|p:NativeDecodeProgress|progress(p.completed,p.total);let mut child=NativeDecodeControl::new(remaining,&mut callback);let value=child.copy_text(text);(value,child.owned_bytes())})?}
fn export(_: &str,_:&ArtifactDialect,payload:&IoPayload,control:&mut SqliteSnapshotControl<'_>)->IoResult<SqliteDatabase>{
    let text=match payload{IoPayload::Text(v)=>v.as_str(),IoPayload::Binary(v)=>std::str::from_utf8(v).map_err(|e|IoError::from_value_error(ValueError::new(ValueRefusalKind::InvalidValue,e.to_string())))?};let literal=copy_decode(text,SqliteSnapshotPhase::DecodeNative,control).map_err(IoError::from_value_error)?;control.checkpoint(SqliteSnapshotPhase::ProjectSnapshot,0,1).map_err(IoError::from_value_error)?;
    let mut values=reserve(2,control).map_err(IoError::from_value_error)?;values.push(SqliteValue::Integer(1));values.push(SqliteValue::Text(literal));let mut rows=reserve(1,control).map_err(IoError::from_value_error)?;rows.push(SqliteRow{rowid:1,values});let name=copy_decode("transfer_literal",SqliteSnapshotPhase::ProjectSnapshot,control).map_err(IoError::from_value_error)?;let sql=copy_decode(DOMAIN,SqliteSnapshotPhase::ProjectSnapshot,control).map_err(IoError::from_value_error)?;let mut tables=reserve(1,control).map_err(IoError::from_value_error)?;tables.push(SqliteTable{name,sql,rows});control.checkpoint(SqliteSnapshotPhase::ProjectSnapshot,1,1).map_err(IoError::from_value_error)?;Ok(IoOutcome::clean(SqliteDatabase{tables}))
}
fn import(_: &str,_:&ArtifactDialect,database:SqliteDatabase,encoding:SnapshotEncoding,control:&mut SqliteSnapshotControl<'_>)->IoResult<IoPayload>{
    let literal=copy_decode(database.table("transfer_literal").map_err(IoError::from_value_error)?.single_row().map_err(IoError::from_value_error)?.text(1).map_err(IoError::from_value_error)?,SqliteSnapshotPhase::ReconstructSnapshot,control).map_err(IoError::from_value_error)?;
    let bytes=control.allocation_stage(SqliteSnapshotPhase::EncodeNative,|remaining,progress|{let mut callback=|p:NativeEncodeProgress|progress(p.completed,p.total);let mut child=NativeEncodeControl::new(remaining,&mut callback);let result=child.copy_bytes(literal.as_bytes());(result,child.owned_bytes())}).map_err(IoError::from_value_error)?.map_err(IoError::from_value_error)?;
    let value=match encoding{SnapshotEncoding::Binary=>IoPayload::Binary(bytes),SnapshotEncoding::Text=>IoPayload::Text(String::from_utf8(bytes).map_err(|e|IoError::from_value_error(ValueError::new(ValueRefusalKind::InvariantViolated,e.to_string())))?)};Ok(IoOutcome::clean(value))
}
fn publish(){let provider=store::ArtifactSqliteSnapshotCodec{schema:DOMAIN.into(),snapshot_type:None,export,import};let codec=store::ArtifactCodec{schema:"fixture.sqlite-transfer/v1".into(),extension:"transfer",snapshot_sqlite:Some(provider),pack_schema_hash:[0;32],compile_dsl:|_,_|Box::pin(async{unreachable!("fixture only exercises the declared SQLite endpoint")}),print_mirror:|_,_|Box::pin(async{unreachable!("fixture only exercises the declared SQLite endpoint")}),edit_text_from_envelope:|_|Box::pin(async{unreachable!("fixture has no edits")}),apply_ops_binary:|_,_,_|Box::pin(async{unreachable!("fixture has no edits")}),replay_envelopes:|_,_,_|Box::pin(async{unreachable!("fixture has no edits")})};register_native_snapshot_codec(dialect(),codec).unwrap();}
fn input(encoding:SnapshotEncoding)->IoPayload{let literal=neutral()["literal"].as_str().unwrap().to_string();match encoding{SnapshotEncoding::Binary=>IoPayload::Binary(literal.into_bytes()),SnapshotEncoding::Text=>IoPayload::Text(literal)}}
fn limits()->SqliteDatabaseLimits{SqliteDatabaseLimits{max_allocation_bytes:usize::try_from(neutral()["maximumAllocationBytes"].as_u64().unwrap()).unwrap(),..Default::default()}}
fn independent(bytes:&[u8]){let script="import{Database}from'bun:sqlite';const d=Database.deserialize(new Uint8Array(await Bun.stdin.arrayBuffer()));if(d.query('PRAGMA integrity_check').get().integrity_check!=='ok')throw Error('integrity');const r=d.query('SELECT literal FROM transfer_literal WHERE id=1').get();console.log(JSON.stringify(r));d.close();";let mut child=Command::new("bun").args(["-e",script]).stdin(Stdio::piped()).stdout(Stdio::piped()).stderr(Stdio::piped()).spawn().unwrap();child.stdin.take().unwrap().write_all(bytes).unwrap();let output=child.wait_with_output().unwrap();assert!(output.status.success(),"{}",String::from_utf8_lossy(&output.stderr));assert_eq!(serde_json::from_slice::<serde_json::Value>(&output.stdout).unwrap()["literal"],neutral()["literal"]);}
#[semio_framework_async_macros::async_test]
async fn sqlite_snapshot_transfer_allocation_export_retains_native_before_metadata_and_physical_output(){
    publish();let from=ArtifactDialect::from(dialect());let sqlite=ArtifactDialect::from(SQLITE_SNAPSHOT);let route=io_route(&from,&sqlite,1).await.unwrap().value;
    for encoding in [SnapshotEncoding::Binary,SnapshotEncoding::Text]{let payload=input(encoding);let mut yes=|_|true;let mut direct=SqliteSnapshotControl::new(&mut yes,limits());let domain=export("fixture.sqlite-transfer/v1",&from,&payload,&mut direct).unwrap().value;let used=limits().max_allocation_bytes-direct.allocation_remaining_bytes();assert_eq!(domain.table("transfer_literal").unwrap().single_row().unwrap().text(1).unwrap(),neutral()["literal"].as_str().unwrap());let mut stages=Vec::new();let file=io_run_with_snapshot_control(&route,payload.clone(),limits(),&mut |p|{stages.push(p.phase);true}).await.unwrap().value;let IoPayload::Binary(bytes)=file else{panic!("SQLite endpoint must return binary")};independent(&bytes);assert!(bytes.len()>used);for phase in [SqliteSnapshotPhase::DecodeNative,SqliteSnapshotPhase::ProjectSnapshot,SqliteSnapshotPhase::WritePages]{assert!(stages.contains(&phase));}assert!(io_run_with_snapshot_control(&route,payload,SqliteDatabaseLimits{max_allocation_bytes:used,..limits()},&mut |_|true).await.is_err(),"native backing exhausts the transfer allowance before metadata and SQLite pages may allocate");}
}
#[semio_framework_async_macros::async_test]
async fn sqlite_snapshot_transfer_allocation_import_retains_physical_before_reconstruction_and_native_output(){
    publish();let into=ArtifactDialect::from(dialect());let sqlite=ArtifactDialect::from(SQLITE_SNAPSHOT);let export_route=io_route(&into,&sqlite,1).await.unwrap().value;let import_route=io_route(&sqlite,&into,1).await.unwrap().value;
    for encoding in [SnapshotEncoding::Binary,SnapshotEncoding::Text]{let payload=input(encoding);let file=io_run_with_snapshot_control(&export_route,payload.clone(),limits(),&mut |_|true).await.unwrap().value;let mut yes=|_|true;let mut direct=SqliteSnapshotControl::new(&mut yes,limits());let domain=export("fixture.sqlite-transfer/v1",&into,&payload,&mut SqliteSnapshotControl::new(&mut |_|true,limits())).unwrap().value;assert_eq!(import("fixture.sqlite-transfer/v1",&into,domain,encoding,&mut direct).unwrap().value,payload);let used=limits().max_allocation_bytes-direct.allocation_remaining_bytes();assert_eq!(used,neutral()["literal"].as_str().unwrap().len()*usize::try_from(neutral()["importCopies"].as_u64().unwrap()).unwrap());let mut stages=Vec::new();assert_eq!(io_run_with_snapshot_control(&import_route,file.clone(),limits(),&mut |p|{stages.push(p.phase);true}).await.unwrap().value,payload);for phase in [SqliteSnapshotPhase::ReadPages,SqliteSnapshotPhase::ReconstructSnapshot,SqliteSnapshotPhase::EncodeNative]{assert!(stages.contains(&phase));}assert!(io_run_with_snapshot_control(&import_route,file,SqliteDatabaseLimits{max_allocation_bytes:used,..limits()},&mut |_|true).await.is_err(),"physical relational ownership must leave less allowance for reconstruction and native output");}
}
